CREATE OR REPLACE FUNCTION battery_audit_events_immutable_fn() RETURNS trigger AS $fn$
BEGIN
  -- The one DELETE allowed: retention moving a row out of the hot table. The row
  -- must be past the hot floor, and an identical copy must already be archived,
  -- so a row can leave this table only by having arrived there first.
  IF TG_OP = 'DELETE'
     AND OLD.occurred_at < now() - interval '90 days'
     AND EXISTS (
       SELECT 1 FROM battery_audit_event_archive a
       WHERE a.id = OLD.id
         AND (a.sequence, a.organization_id, a.record_id, a.version, a.occurred_at, a.resource, a.action, a.action_type, a.data, a.changed_attributes, a.metadata, a.previous_hash, a.hash) IS NOT DISTINCT FROM (OLD.sequence, OLD.organization_id, OLD.record_id, OLD.version, OLD.occurred_at, OLD.resource, OLD.action, OLD.action_type, OLD.data, OLD.changed_attributes, OLD.metadata, OLD.previous_hash, OLD.hash)
     ) THEN
    RETURN OLD;
  END IF;

  RAISE EXCEPTION 'battery_audit_events is append-only; % is not permitted', TG_OP
    USING ERRCODE = 'restrict_violation',
          HINT = 'Correct a wrong entry by recording a new one.';
END;
$fn$ LANGUAGE plpgsql;
